import { randomUUID } from "node:crypto";

/**
 * `plan_id_new` returns one lowercase RFC 4122 UUIDv4 generated by Node's
 * CSPRNG (`crypto.randomUUID`). It is the only sanctioned identity source for
 * new Markdown plans: Planner has no shell, and model-generated UUIDs are not
 * accepted. The tool reads and writes nothing; uniqueness is still verified by
 * Planner against the exact proposed path before creating the plan file.
 */
export const PLAN_ID_TOOL_NAME = "plan_id_new";

export const planIdToolInputSchema: Record<string, unknown> = {
  type: "object",
  properties: {},
  additionalProperties: false,
};

type PlanIdToolResult = { content: string; metadata: { title: string } };

export function createPlanIdTool(): {
  name: string;
  description: string;
  input: Record<string, unknown>;
  execute: (input: unknown) => Promise<PlanIdToolResult>;
} {
  return {
    name: PLAN_ID_TOOL_NAME,
    description:
      "Return one new lowercase RFC 4122 UUIDv4 from a cryptographically secure source, as JSON {\"id\": \"...\"}. Use it as the immutable Markdown plan id. Reads and writes no files.",
    input: planIdToolInputSchema,
    async execute() {
      const id = randomUUID();
      return {
        content: JSON.stringify({ id }, null, 2),
        metadata: { title: "New plan id" },
      };
    },
  };
}
